import {newGame,derive,commit,uid,currentClock,configPlan,applyPlan} from './engine.js';
import {parseGameDate,parseStartTime,opponentFromSpeech,scheduleLabel,localDate} from './schedule.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createLibraryUI(bridge){let collections=[],games=[],loaded=false,activeCollection=null,dirty=false,syncing=null,syncTimer=null,syncError='',recognition=null;
async function api(path,options={}){const r=await fetch('/api/'+path,{...options,headers:{'content-type':'application/json','x-courtside-account':bridge.getAccountId(),...options.headers},cache:'no-store'});let b;try{b=await r.json();}catch{throw Error('Collections could not be loaded. Reconnect and try again.');}if(r.status===401){window.dispatchEvent(new Event('account-expired'));}if(!r.ok){const e=Error(b.error||'Could not save or load games.');e.status=r.status;throw e;}return b;}
function notice(text,error=false){$('#libraryNotice').innerHTML=text?`<div class="warning ${error?'error':''}">${esc(text)}${error?' <button id="retryLibrary">Retry connection</button>':''}</div>`:'';$('#retryLibrary')?.addEventListener('click',()=>boot());}
function writeLocal(){bridge.writeLocal();}
function queue(){const s=bridge.getState();if(!s.transactions.length&&!s.meta)return;dirty=true;s.syncPending=true;writeLocal();$('#saveStatus').textContent='Saving…';clearTimeout(syncTimer);syncTimer=setTimeout(()=>flush().catch(()=>{}),350);}
async function flush(){clearTimeout(syncTimer);if(syncing){await syncing;if(dirty)return flush();return;}if(!dirty)return;const s=bridge.getState(),snapshot=structuredClone(s),id=s.id;dirty=false;$('#saveStatus').textContent='Saving…';syncing=(async()=>{try{const result=await api('games/'+encodeURIComponent(id),{method:'PUT',body:JSON.stringify({game:snapshot,revision:snapshot.cloudRevision||0})});if(bridge.getState().id===id){bridge.getState().cloudRevision=result.revision;if(!dirty)bridge.getState().syncPending=false;writeLocal();}games=games.filter(g=>g.id!==id);games.unshift({...result.summary,revision:result.revision});syncError='';$('#saveStatus').textContent=dirty?'Saving…':'Saved to your account';}catch(e){dirty=true;syncError=e.message;$('#saveStatus').textContent='Local backup · not synced';notice(e.message,true);bridge.feedback(e.message,true);throw e;}finally{syncing=null;}})();await syncing;if(dirty)return flush();}
async function reload(){const data=await api('library');collections=data.collections;games=data.games;loaded=true;}
function hasLocal(){const s=bridge.getState();return !!(s.meta||s.transactions.length);}
function updateGameDetails(){const s=bridge.getState(),d=derive(s),c=collections.find(c=>c.id===s.meta?.collectionId);$('#gameDetails').textContent=(c?c.name+' · ':'')+d.settings.home+' vs '+d.settings.away+' · '+scheduleLabel(s.meta);}
function hideRecorder(){bridge.stopMic();stopDictation();const s=bridge.getState();if(s.clock.running){commit(s,[{type:'CLOCK_STOP'}],'Returned to games menu',{...currentClock(s),running:false});queue();}$('#gameSurface').hidden=true;$('#library').hidden=false;}
async function menu(collectionId=null){hideRecorder();activeCollection=collectionId;renderMenu();let error;try{await flush();}catch(e){error=e;}try{await reload();renderMenu();}catch(e){error=error||e;}notice(error?.message||'',!!error);}
function row(g){const final=g.status==='final',score=final||g.status==='in-progress'?`${g.score.home} – ${g.score.away}`:'—';return `<article class="gameRow"><div><h3>${esc(g.home)} <span class="muted">vs</span> ${esc(g.opponent)}</h3><p class="muted">${esc(scheduleLabel(g))}</p><span class="badge">${final?'FINAL':g.status==='in-progress'?'IN PROGRESS':'SCHEDULED'}</span></div><strong class="result">${score}</strong><button data-open-game="${esc(g.id)}">${final?'View box score':'Open game'} →</button></article>`;}
function renderMenu(){const content=$('#libraryContent');content.className='';const c=collections.find(c=>c.id===activeCollection);const sorted=list=>[...list].sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(b.startTime||'').localeCompare(a.startTime||'')||b.updatedAt.localeCompare(a.updatedAt));if(!loaded){content.innerHTML=hasLocal()?'<div class="menuBanner"><h2>Your local game is safe</h2><p>Continue scoring offline. Your account history will load when reconnected.</p><button id="resumeLocal">Open local game</button></div>':'<div class="panel emptyMenu">Your collections will appear here when connected.</div>';$('#resumeLocal')?.addEventListener('click',()=>openLocal());return;}
if(c){const list=games.filter(g=>g.collectionId===c.id),finals=list.filter(g=>g.status==='final');content.innerHTML=`<button id="allCollections">← All collections</button><div class="sectionhead collectionHeading"><div><span class="eyebrow">SEASON COLLECTION</span><h2>${esc(c.name)}</h2><p class="muted" style="margin-top:8px">${esc(c.teamName)} · ${list.length} ${list.length===1?'game':'games'} · ${finals.length} completed</p></div><button id="addSeasonGame" class="primary">+ New game</button></div>${list.length?sorted(list).map(row).join(''):'<div class="panel emptyMenu"><h3>No games in this collection yet</h3><p>Create a game to start this season.</p></div>'}`;$('#allCollections').onclick=()=>menu();$('#addSeasonGame').onclick=()=>newGameForm(c.id);}
else{const unfinished=games.filter(g=>g.status!=='final'),uncollected=games.filter(g=>!g.collectionId),local=bridge.getState();content.innerHTML=`${hasLocal()&&(local.syncPending||!games.some(g=>g.id===local.id))?'<div class="menuBanner"><h2>Your local game is safe</h2><p>Open it to continue, export a backup, or choose its season in Game details.</p><button id="resumeLocal">Open local game</button></div>':''}<div class="sectionhead"><h2>Collections</h2><span class="muted">${collections.length} ${collections.length===1?'collection':'collections'}</span></div><div class="collections">${collections.map(c=>{const list=games.filter(g=>g.collectionId===c.id);return `<button class="collection" data-collection="${esc(c.id)}"><span class="eyebrow">SEASON</span><h2>${esc(c.name)}</h2><span class="muted">${esc(c.teamName)} · ${list.length} ${list.length===1?'game':'games'} · ${list.filter(g=>g.status==='final').length} final</span></button>`;}).join('')||'<div class="panel emptyMenu" style="grid-column:1/-1"><h2>Start with a collection</h2><p class="muted">Use a name like Wolves 2026 to keep a season’s games together.</p><div class="actions"><button id="firstCollection" class="primary">Create a collection</button></div></div>'}</div>${unfinished.length?`<section class="menuSection"><h2>Ready to play</h2>${sorted(unfinished).slice(0,10).map(row).join('')}</section>`:''}${uncollected.some(g=>g.status==='final')?`<section class="menuSection"><h2>Games without a collection</h2><p class="muted">Open a game and choose Game details to add it to a season.</p>${sorted(uncollected.filter(g=>g.status==='final')).map(row).join('')}</section>`:''}<p class="muted" style="margin-top:24px">Collections and saved games are available on your signed-in devices. Offline changes remain on this device until synced.</p>`;content.querySelectorAll('[data-collection]').forEach(b=>b.onclick=()=>menu(b.dataset.collection));$('#firstCollection')?.addEventListener('click',()=>collectionForm());$('#resumeLocal')?.addEventListener('click',()=>openLocal());}
content.querySelectorAll('[data-open-game]').forEach(b=>b.onclick=()=>openGame(b.dataset.openGame));}
function openLocal(){hideRecorder();$('#library').hidden=true;$('#gameSurface').hidden=false;bridge.render();bridge.setView(bridge.getState().clock.final?'box':'live');updateGameDetails();if(syncError)bridge.feedback(syncError,true);}
async function openGame(id,skipFlush=false){try{if(!skipFlush)await flush();const result=await api('games/'+encodeURIComponent(id));bridge.stopMic();const s=result.game;s.cloudRevision=result.revision;s.syncPending=false;if(s.clock.running){s.clock={...currentClock(s),running:false,wall:Date.now()};commit(s,[{type:'CLOCK_STOP'}],'Game opened on this device',{running:false});}bridge.replaceState(s);writeLocal();openLocal();if(s.transactions.at(-1)?.events.some(e=>e.raw==='Game opened on this device'))queue();}catch(e){notice(e.message,true);if(e.status===409){modal('<h2>This game changed on another device</h2><p>Download your local game as a backup, then open the saved account version. Your backup keeps any changes that have not synced.</p><button id="resolveGameConflict" class="primary">Back up local game & open saved version</button>');$('#resolveGameConflict').onclick=async()=>{bridge.exportGame();dirty=false;syncError='';$('#dialog').close();await openGame(id,true);};}}}
function modal(html){bridge.showDialog(html);$('#dialog').addEventListener('close',stopDictation,{once:true});}
function formError(text,error=true){const p=$('#formStatus');if(p){p.textContent=text;p.className='formNotice '+(error?'error':'success');}}
function collectionForm(onCreated){modal(`<h2>New collection</h2><form id="collectionForm" class="formStack"><label>Collection name<div class="fieldvoice"><input id="collectionName" placeholder="Wolves 2026" maxlength="80" required><button type="button" data-dictate="collectionName" aria-label="Speak collection name">Speak</button></div></label><label>Your team<input id="collectionTeam" placeholder="Wolves" maxlength="60" required></label><p id="formStatus" class="formNotice" role="status">Keep all of a season’s games in one place.</p><button class="primary">Create collection</button></form>`);$('#collectionName').oninput=()=>{if(!$('#collectionTeam').dataset.edited)$('#collectionTeam').value=$('#collectionName').value.replace(/\s*20\d{2}(?:[ /-]\d{2,4})?\s*$/,'').trim();};$('#collectionTeam').oninput=()=>$('#collectionTeam').dataset.edited='true';bindDictation();$('#collectionForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const c=await api('collections',{method:'POST',body:JSON.stringify({id:uid(),name:$('#collectionName').value.trim(),teamName:$('#collectionTeam').value.trim()})});await reload();$('#dialog').close();renderMenu();if(onCreated)onCreated(c);else menu(c.id);}catch(err){formError(err.message);button.disabled=false;}};}
function legacyGameDetails(collectionId=activeCollection,draft=null,editing=false){if(!loaded){notice('Connect to load or create your collections first.',true);return;}let createdGameId=null;const original=editing?bridge.getState():null,meta=original?.meta||{},s=original?derive(original):null,data=draft||{collectionId:collectionId||meta.collectionId||'',opponent:s?.settings.away||'',date:meta.date||localDate(),startTime:meta.startTime||''};modal(`<h2>${editing?'Game details':'New game'}</h2><form id="gameForm" class="formStack"><label>Collection<select id="gameCollection"><option value="">No collection</option>${collections.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}<option value="__new__">+ Create a new collection…</option></select></label><label>Opponent<div class="fieldvoice"><input id="gameOpponent" maxlength="60" placeholder="Who are you playing?" value="${esc(data.opponent)}" required ${editing&&s.clock.started?'disabled':''}><button type="button" data-dictate="gameOpponent" ${editing&&s.clock.started?'disabled':''}>Speak</button></div></label><div class="row"><label>Game date<div class="fieldvoice"><input id="gameDate" type="date" value="${esc(data.date)}" required><button type="button" data-dictate="gameDate">Speak</button></div></label><label>Start time <span class="muted">Optional · leave blank if unknown</span><div class="fieldvoice"><input id="gameTime" type="time" value="${esc(data.startTime)}"><button type="button" data-dictate="gameTime">Speak</button></div></label></div>${editing?'':'<label class="review"><span><input id="reuseRoster" type="checkbox" checked> Use roster and rules from the last game in this collection</span></label>'}<p id="formStatus" class="formNotice" role="status">Speak each field, then check the details before saving. You can skip the start time.</p><button class="primary">${editing?'Save game details':'Create game'}</button></form>`);$('#gameCollection').value=data.collectionId;$('#gameCollection').onchange=()=>{if($('#gameCollection').value==='__new__'){const draft=readForm();draft.collectionId='';collectionForm(c=>newGameForm(c.id,{...draft,collectionId:c.id},editing));}};bindDictation();$('#gameForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const details=readForm();if(details.collectionId==='__new__')throw Error('Create or select a collection.');if(!details.opponent.trim()||!details.date)throw Error('Enter an opponent and game date.');await flush();if(createdGameId&&bridge.getState().id===createdGameId){$('#dialog').close();openLocal();bridge.setView('setup');return;}const c=collections.find(c=>c.id===details.collectionId);if(editing){const game=bridge.getState();game.meta={...game.meta,...details,collectionId:details.collectionId||null};if(!game.clock.started&&details.opponent!==derive(game).settings.away)commit(game,[{type:'CONFIG',settings:{...derive(game).settings,away:details.opponent}}],'Updated opponent');queue();await flush();$('#dialog').close();bridge.render();updateGameDetails();return;}
let previous=null;if($('#reuseRoster')?.checked&&c){const last=games.find(g=>g.collectionId===c.id);if(last)previous=(await api('games/'+encodeURIComponent(last.id))).game;}const game=newGame(),prev=previous?derive(previous):null;game.meta={...details,collectionId:details.collectionId||null,createdAt:new Date().toISOString()};commit(game,[{type:'CONFIG',settings:{...(prev?.settings||derive(game).settings),home:c?.teamName||prev?.settings.home||'Your team',away:details.opponent}},...(prev?[{type:'ROSTER',roster:prev.roster.filter(p=>p.team==='home')}]:[])],'Created scheduled game',{seconds:prev?.settings.length||480});createdGameId=game.id;bridge.replaceState(game);queue();await flush();$('#dialog').close();openLocal();bridge.setView('setup');bridge.feedback('Game created. Choose your roster and starters before tip-off.');}catch(err){formError(err.message);b.disabled=false;}};}
function newGameForm(collectionId=activeCollection,draft=null,editing=false){
 if(editing)return legacyGameDetails(collectionId,draft,true);
 if(!loaded){notice('Connect to load or create your collections first.',true);return;}
 const data={collectionId:collectionId||'',opponent:'',date:localDate(),startTime:'',periods:4,length:8,overtime:4,timeouts:5,foulLimit:5,autoAssists:true,reuseRoster:true,...draft};let step=0,createdGameId=null;
 function capture(){const f=$('#gameForm');for(const el of f.querySelectorAll('input,select'))if(el.name)data[el.name]=el.type==='checkbox'?el.checked:el.type==='number'?+el.value:el.value;}
 function draw(){stopDictation();modal(`<span class="eyebrow">NEW GAME · STEP ${step+1} OF 3</span><h2>${['Teams & season','Game format','Date & tip-off'][step]}</h2><nav class="wizardSteps" aria-label="Game setup progress">${['Teams','Rules','When'].map((t,i)=>`<span class="${i===step?'active':''}">${i+1}. ${t}</span>`).join('')}</nav><form id="gameForm" class="formStack">${step===0?`<label>Collection<select id="gameCollection" name="collectionId"><option value="">No collection</option>${collections.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}<option value="__new__">+ Create a new collection…</option></select></label><label>Opponent<div class="fieldvoice"><input id="gameOpponent" name="opponent" maxlength="60" placeholder="Who are you playing?" value="${esc(data.opponent)}" required><button type="button" data-dictate="gameOpponent">Speak</button></div></label><label class="review"><span><input id="reuseRoster" name="reuseRoster" type="checkbox" ${data.reuseRoster?'checked':''}> Copy your roster from the last game in this collection</span></label>`:step===1?`<label>Format<select id="gameFormat"><option value="4">Four quarters</option><option value="2">Two halves</option><option value="custom">Custom periods</option></select></label><div class="fields"><label>Number of periods<input id="gamePeriods" name="periods" type="number" min="1" max="12" value="${data.periods}" required></label><label>Minutes per period<input name="length" type="number" min="1" max="60" value="${data.length}" required></label><label>Overtime minutes<input name="overtime" type="number" min="1" max="20" value="${data.overtime}" required></label><label>Timeouts per team<input name="timeouts" type="number" min="0" max="20" value="${data.timeouts}" required></label><label>Foul-out limit<input name="foulLimit" type="number" min="1" max="10" value="${data.foulLimit}" required></label></div><label class="review"><span><input name="autoAssists" type="checkbox" ${data.autoAssists?'checked':''}> Automatically credit assists from passing chains</span></label><p class="muted">Credits the last passer on a made basket when the scorer does not dribble, drive, or step back after receiving the ball.</p>`:`<label>Game date<div class="fieldvoice"><input id="gameDate" name="date" type="date" value="${esc(data.date)}" required><button type="button" data-dictate="gameDate">Speak</button></div></label><label>Start time <span class="muted">Optional</span><div class="fieldvoice"><input id="gameTime" name="startTime" type="time" value="${esc(data.startTime)}"><button type="button" data-dictate="gameTime">Speak</button></div></label><button type="button" id="skipTime">No start time / decide later</button><div class="gameRecap"><strong>${esc(collections.find(c=>c.id===data.collectionId)?.name||'No collection')} · vs ${esc(data.opponent)}</strong><p>${data.periods} ${data.periods===2?'halves':'periods'} × ${data.length} minutes · ${data.overtime}-minute overtime</p><p>Automatic assists ${data.autoAssists?'on':'off'}</p></div>`}<p id="formStatus" class="formNotice" role="status">${step===2?'Say a date and time, type them, or leave the start time blank.':'You can go back to change any detail.'}</p><div class="actions">${step?'<button type="button" id="wizardBack">← Back</button>':''}<button class="primary">${step===2?'Create game':'Next →'}</button></div></form>`);
 if(step===0){$('#gameCollection').value=data.collectionId;$('#gameCollection').onchange=()=>{capture();if(data.collectionId==='__new__'){data.collectionId='';collectionForm(c=>newGameForm(c.id,{...data,collectionId:c.id}));}};}
 if(step===1){$('#gameFormat').value=[2,4].includes(data.periods)?String(data.periods):'custom';$('#gameFormat').onchange=e=>{if(e.target.value!=='custom')$('#gamePeriods').value=e.target.value;};$('#gamePeriods').oninput=()=>$('#gameFormat').value='custom';}
 $('#skipTime')?.addEventListener('click',()=>{$('#gameTime').value='';});$('#wizardBack')?.addEventListener('click',()=>{capture();step--;draw();});bindDictation();
 $('#gameForm').onsubmit=async e=>{e.preventDefault();capture();if(step<2){step++;draw();return;}const b=e.submitter;b.disabled=true;try{await flush();if(createdGameId&&bridge.getState().id===createdGameId){$('#dialog').close();openLocal();bridge.setView('setup');return;}const c=collections.find(c=>c.id===data.collectionId);let prev=null;if(data.reuseRoster&&c){const last=games.find(g=>g.collectionId===c.id);if(last)prev=derive((await api('games/'+encodeURIComponent(last.id))).game);}const game=newGame(),settings={...derive(game).settings,home:c?.teamName||prev?.settings.home||'Your team',away:data.opponent,periods:data.periods,length:data.length*60,overtime:data.overtime*60,timeouts:data.timeouts,foulLimit:data.foulLimit,autoAssists:data.autoAssists};applyPlan(game,configPlan(settings,game),'Game setup');if(prev)commit(game,[{type:'ROSTER',roster:prev.roster.filter(p=>p.team==='home')}],'Copied season roster');game.meta={collectionId:data.collectionId||null,opponent:data.opponent,date:data.date,startTime:data.startTime,createdAt:new Date().toISOString()};createdGameId=game.id;bridge.replaceState(game);queue();await flush();$('#dialog').close();openLocal();bridge.setView('setup');bridge.feedback('Game created. Add your roster and choose five starters before tip-off.');}catch(err){formError(err.message);b.disabled=false;}};
 }draw();
}
function readForm(){return {collectionId:$('#gameCollection').value,opponent:$('#gameOpponent').value.trim(),date:$('#gameDate').value,startTime:$('#gameTime').value||''};}
function stopDictation(){const r=recognition;recognition=null;try{r?.abort();}catch{}if(r)bridge.releaseRecognition();}
function bindDictation(){document.querySelectorAll('[data-dictate]').forEach(b=>b.onclick=async()=>{stopDictation();bridge.stopMic();const target=b.dataset.dictate,Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition)return formError('Voice is unavailable in this browser. Type the field or open Chrome.');const r=new Recognition();recognition=r;r.lang='en-US';r.continuous=false;r.interimResults=false;r.onstart=()=>formError('Listening… '+(target==='gameDate'?'Say “September 18” or “Friday.”':target==='gameTime'?'Say “7 PM,” or “no time.”':'Say the name.'),false);r.onresult=e=>{if(recognition!==r)return;const raw=e.results[0][0].transcript;try{const field=$('#'+target);if(!field)return;field.value=target==='gameDate'?parseGameDate(raw):target==='gameTime'?parseStartTime(raw):target==='gameOpponent'?opponentFromSpeech(raw):raw.replace(/[.!]+$/,'');field.dispatchEvent(new Event('input',{bubbles:true}));formError(`Heard “${raw}”. Check the ${target==='gameDate'?'date':target==='gameTime'?'time':'name'} before saving.`,false);}catch(err){formError(`Heard “${raw}”. ${err.message}`);}};r.onerror=e=>{if(recognition===r)formError(e.error==='not-allowed'?'Allow microphone access in Chrome, or type the field.':e.error==='network'?'The browser speech service is unreachable. Your internet may still be working. Try offline speech or open this site in standalone Chrome; you can also type this field.':'Voice was interrupted. Try again or type the field.');};r.onend=()=>{if(recognition===r){recognition=null;bridge.releaseRecognition();}};try{await bridge.startRecognition(r);}catch(e){if(recognition===r){recognition=null;bridge.releaseRecognition();formError(e.message||'Microphone could not start. Try again or type the field.');}}});}
async function boot(){try{await reload();const local=bridge.getState();if(hasLocal()&&(local.syncPending||!local.cloudRevision)){const cloud=games.find(g=>g.id===local.id);if(!cloud||local.cloudRevision){dirty=true;await flush();}else{syncError='A saved copy of your local game is already in your account. Open it from the menu, or export the local game first.';notice(syncError,true);}}if(!syncError)notice('');renderMenu();$('#saveStatus').textContent=dirty?'Local backup · not synced':'Saved to your account';}catch(e){notice(e.message,true);renderMenu();$('#saveStatus').textContent='Offline · local backup';}}
$('#newCollectionMenu').onclick=()=>collectionForm();$('#newGameMenu').onclick=()=>newGameForm();$('#backMenu').onclick=()=>menu(bridge.getState().meta?.collectionId||null);$('#editGameDetails').onclick=()=>newGameForm(null,null,true);$('.brand').onclick=e=>{e.preventDefault();menu();};window.addEventListener('online',()=>boot());window.addEventListener('visibilitychange',()=>{if(!document.hidden&&$('#gameSurface').hidden)boot();});window.addEventListener('pagehide',stopDictation);hideRecorder();queueMicrotask(boot);window.addEventListener('pageshow',e=>{if(e.persisted)menu();});
return {queue,flush,menu,newGame:()=>newGameForm(),openLocal,updateGameDetails,prepareImport(game){game.id=uid();delete game.cloudRevision;game.syncPending=true;game.meta={...game.meta,collectionId:collections.some(c=>c.id===game.meta?.collectionId)?game.meta.collectionId:null};return game;}};
}
